  \draw (0,0) to[battery1, l=12\,V] (0,4);
  % top branch: fixed resistor R, with voltmeter in parallel across it
  \draw (0,4) -- (2,4) to[R, l=$R$] (5,4) -- (8,4);
  % right side: thermistor T
  \draw (8,4) to[thermistor, l=$T$] (8,0);
  % bottom wire
  \draw (8,0) -- (0,0);
  % voltmeter connected across R
  \draw (2,4) -- (2,5.5) to[voltmeter, l=V] (5,5.5) -- (5,4);
  % caption
  \node[below] at (4,-0.8) {\textbf{Fig. 2.1}};
\end{tikzpicture}
